using System.Diagnostics; namespace CubeAntivirus.Modules; public sealed record ProcessEntry(string Name, int Pid, string Status); public static class ProcessManager { public static IReadOnlyList<ProcessEntry> GetProcesses() { var list = new List<ProcessEntry>(); foreach (var p in Process.GetProcesses()) { try { list.Add(new(p.ProcessName, p.Id, "Running")); } catch (Exception ex) when (ex is InvalidOperationException or System.ComponentModel.Win32Exception) { } finally { p.Dispose(); } } return list.OrderBy(x => x.Name).ToArray(); } public static bool LooksLikeMiner(string? args) => !string.IsNullOrWhiteSpace(args) && new[] { "--stratum", "stratum+tcp://", "stratum+ssl://", "-o pool" }.Any(x => args.Contains(x, StringComparison.OrdinalIgnoreCase)); }